const e={71:{dayName:"Dia 71 — Segunda-feira",title:"Be Going To (Planos e Intenções)",focus:"Falar de planos já decididos com be going to.",vocab:[{en:"Going to",pt:"Vou / Vamos (plano)"},{en:"Plan",pt:"Plano"},{en:"Intention",pt:"Intenção"},{en:"Future",pt:"Futuro"},{en:"Soon",pt:"Em breve"},{en:"Later",pt:"Mais tarde"},{en:"Next week",pt:"Próxima semana"},{en:"Next month",pt:"Próximo mês"},{en:"Next year",pt:"Próximo ano"},{en:"Career",pt:"Carreira"}],grammar:{title:"Be Going To",rule:"AM/IS/ARE + GOING TO + verbo base: I am going to study. She is going to travel. Negativa: am not / isn't / aren't going to. Pergunta: Are you going to...?",table:[{form:"Plano decidido",example:"I am going to learn English for my career.",pt:"Vou aprender inglês para minha carreira."},{form:"Negativa",example:"We aren't going to launch today.",pt:"Não vamos lançar hoje."},{form:"Pergunta",example:"Are you going to study tonight? Yes, I am.",pt:"Você vai estudar hoje à noite? Sim."}]},reading:{title:"My Future Plans",text:"I am going to build a portfolio next month. I am going to learn React in the next weeks. My friend is going to help me with the backend. We are going to launch our first app in December. I am not going to stop studying English. My career is going to grow.",translation:"Vou construir um portfólio no próximo mês. Vou aprender React nas próximas semanas. Meu amigo vai me ajudar com o backend. Vamos lançar nosso primeiro app em dezembro. Não vou parar de estudar inglês. Minha carreira vai crescer."},quiz:[{q:"Complete: 'I ___ going to study tonight.'",options:["am","is","are"],ans:"am"},{q:"Complete: 'She is ___ to help me.'",options:["going","go","goes"],ans:"going"},{q:"Negativa: 'We ___ going to launch today.'",options:["aren't","isn't","don't"],ans:"aren't"}],chunks:[{en:"I am going to learn React",pt:"vou aprender React"},{en:"we are going to launch an app",pt:"vamos lançar um app"},{en:"I am not going to stop",pt:"não vou parar"}],listeningScript:"What are you going to do this weekend? I am going to study and practice coding. Are you going to rest? A little. Are you going to visit your family? Next month, I am going to visit them.",speakingPrompt:"Conte seus planos: 'I am going to study tonight. I am going to build a project. I am not going to give up.'",lightReading:"Roadmaps are written in going to: we are going to ship, we are going to refactor, we are going to scale — planning language for engineering.",journalPrompt:"Today is Day 71. I learned be going to.",tip:"DICA DE PRONÚNCIA: 'going to' soa como 'gonna' na fala natural. Você pode escrever 'I am going to', mas ao falar: 'I'm gonna study'. As duas formas são certas."},72:{dayName:"Dia 72 — Terça-feira",title:"Will (Decisões Instantâneas & Promessas)",focus:"Usar will para decisões na hora, promessas e ofertas.",vocab:[{en:"Will",pt:"Vai / Vou (futuro)"},{en:"Promise",pt:"Promessa"},{en:"Offer",pt:"Oferta / Oferecer"},{en:"Help",pt:"Ajudar"},{en:"Call",pt:"Ligar"},{en:"Send",pt:"Enviar"},{en:"Check",pt:"Verificar"},{en:"Do it",pt:"Fazer isso"},{en:"Be there",pt:"Estar lá"},{en:"Wait",pt:"Esperar"}],grammar:{title:"Will",rule:"WILL + verbo base (I will call = I'll call). Uso: decisão no momento (I'll take this one!), promessa (I promise I will help), oferta (I'll open the door), previsão sem evidência (It will rain).",table:[{form:"Decisão na hora",example:"This app is cool. I'll download it!",pt:"Este app é legal. Vou baixá-lo!"},{form:"Promessa",example:"I promise I will finish the task today.",pt:"Prometo que terminarei a tarefa hoje."},{form:"Oferta",example:"Don't worry, I'll help you.",pt:"Não se preocupe, eu ajudo você."}]},reading:{title:"Instant Decisions",text:"My computer stopped working at noon. I said: 'I'll fix it myself!' First, I'll check the cables. I'll restart the system. If it doesn't work, I'll call the support team. I promise I will not panic. I will stay calm and solve it step by step.",translation:"Meu computador parou de funcionar ao meio-dia. Eu disse: 'Vou consertá-lo sozinho!' Primeiro, vou verificar os cabos. Vou reiniciar o sistema. Se não funcionar, vou ligar para o suporte. Prometo que não vou entrar em pânico. Vou manter a calma e resolver passo a passo."},quiz:[{q:"Decisão na hora:",options:["I'll take this one!","I am taking this one tomorrow","I took this one"],ans:"I'll take this one!"},{q:"Contração de 'I will':",options:["I'll","I'will","Ill"],ans:"I'll"},{q:"Oferta:",options:["I'll help you","I helping you","I helped you"],ans:"I'll help you"}],chunks:[{en:"I'll check the cables",pt:"vou verificar os cabos"},{en:"I promise I will help",pt:"prometo que vou ajudar"},{en:"I'll call the support",pt:"vou ligar para o suporte"}],listeningScript:"Oh no, my phone is dead! Don't worry, I'll charge it here. Wait, I'll check the charger. Yes, it's fine. I'll come back in five minutes. I promise!",speakingPrompt:"Decisões na hora: 'I'll do it! I'll call you. I'll send the file. I promise I'll study more.'",lightReading:"Will is for here-and-now commitments: 'I'll fix it', 'I'll review the PR' — the instant promise language of every developer.",journalPrompt:"Today is Day 72. I learned will for instant decisions.",tip:"DICA DE ESCRITA: GOING TO = plano pensado antes. WILL = decisão no momento. Em e-mails: 'I am going to attend the meeting' (planejado) vs 'I'll check it right now' (ação imediata)."},73:{dayName:"Dia 73 — Quarta-feira",title:"Will — Previsões & Probably",focus:"Fazer previsões sobre o futuro com will e probably.",vocab:[{en:"Probably",pt:"Provavelmente"},{en:"Maybe",pt:"Talvez"},{en:"Definitely",pt:"Definitivamente"},{en:"Certainly",pt:"Certamente"},{en:"Prediction",pt:"Previsão"},{en:"Technology",pt:"Tecnologia"},{en:"Artificial intelligence",pt:"Inteligência artificial"},{en:"Robot",pt:"Robô"},{en:"Climate",pt:"Clima"},{en:"Change",pt:"Mudança"}],grammar:{title:"Will para Previsões",rule:"WILL + verbo base para previsões sem certeza absoluta: I think AI will change everything. Posição dos advérbios: provavelmente vem depois de will: It will probably rain.",table:[{form:"Previsão",example:"I think the internet will grow faster.",pt:"Acho que a internet crescerá mais rápido."},{form:"Probably",example:"It will probably work tomorrow.",pt:"Provavelmente vai funcionar amanhã."},{form:"Maybe + frase",example:"Maybe I will study abroad.",pt:"Talvez eu estude no exterior."}]},reading:{title:"The Future of Technology",text:"What will the future look like? Artificial intelligence will probably change our jobs. Robots will do many tasks at home. Cars will drive themselves. Maybe doctors will use AI to save more lives. The internet will certainly connect everything. I think English will be even more important. Are you ready for the future?",translation:"Como será o futuro? A inteligência artificial provavelmente mudará nossos empregos. Robôs farão muitas tarefas em casa. Os carros dirigirão sozinhos. Talvez os médicos usem IA para salvar mais vidas. A internet certamente conectará tudo. Acho que o inglês será ainda mais importante. Você está pronto para o futuro?"},quiz:[{q:"Previsão:",options:["AI will change jobs","AI is changing jobs yesterday","AI changed jobs tomorrow"],ans:"AI will change jobs"},{q:"Posição de 'probably':",options:["It will probably work","It probably will work","Probably it will working"],ans:"It will probably work"},{q:"'Maybe' na frase:",options:["Maybe I will study abroad","I maybe study will abroad","Maybe will I study abroad"],ans:"Maybe I will study abroad"}],chunks:[{en:"it will probably work",pt:"provavelmente vai funcionar"},{en:"maybe I will study abroad",pt:"talvez eu estude no exterior"},{en:"the internet will connect everything",pt:"a internet vai conectar tudo"}],listeningScript:"What do you think about the future? I think AI will change many jobs. Maybe some jobs will disappear. But new jobs will certainly appear. English will probably be even more important. Are you ready?",speakingPrompt:"Preveja: 'I think AI will change work. Robots will do tasks. Maybe I will learn more tech. It will be exciting!'",lightReading:"Tech predictions all use will: Moore's law said chips will double, futurists say AI will scale — forecasting is a grammar pattern.",journalPrompt:"Today is Day 73. I learned predictions with will.",tip:"DICA DE LEITURA: ao ler textos sobre futuro, as pistas são: will, maybe, probably, in the future, by 2030. Sublinhe-as para saber que o texto fala de previsão."},74:{dayName:"Dia 74 — Quinta-feira",title:"Present Continuous para Planos Fixos",focus:"Usar o contínuo para compromissos agendados no futuro próximo.",vocab:[{en:"Appointment",pt:"Compromisso"},{en:"Schedule",pt:"Agenda"},{en:"Flight",pt:"Voo"},{en:"Train",pt:"Trem"},{en:"Ticket",pt:"Ingresso / Passagem"},{en:"Reservation",pt:"Reserva"},{en:"Arrival",pt:"Chegada"},{en:"Departure",pt:"Partida"},{en:"Meeting",pt:"Reunião"},{en:"Conference",pt:"Conferência"}],grammar:{title:"Contínuo para Planos",rule:"Quando há horário marcado, o inglês usa o Present Continuous para o futuro: I am meeting him at 3 PM. Dica de tempo: at 3 PM, tomorrow, next Friday.",table:[{form:"Plano marcado",example:"I am flying to São Paulo tomorrow.",pt:"Vou voar para São Paulo amanhã."},{form:"Reunião",example:"We are meeting the client at 10 AM.",pt:"Vamos encontrar o cliente às 10h."},{form:"Contraste",example:"I am going to study (intenção). I am studying at 8 (hora marcada).",pt:"Vou estudar / Estou estudando às 8."}]},reading:{title:"My Busy Schedule",text:"I have a busy schedule this week. Tomorrow I am flying to São Paulo at 7 AM. On Thursday I am meeting the new developers. On Friday we are presenting the project at the conference. Next week I am taking a training course. Everything is arranged and confirmed.",translation:"Tenho uma agenda cheia esta semana. Amanhã estou voando para São Paulo às 7h. Na quinta, estou encontrando os novos desenvolvedores. Na sexta, vamos apresentar o projeto na conferência. Na próxima semana, estou fazendo um curso de treinamento. Tudo está combinado e confirmado."},quiz:[{q:"Plano marcado:",options:["I am flying tomorrow at 7 AM","I fly yesterday","I flew tomorrow"],ans:"I am flying tomorrow at 7 AM"},{q:"Complete: 'We ___ meeting the client at 10.'",options:["are","is","am"],ans:"are"},{q:"'I am taking a course next week' — a ação:",options:["está marcada","é passada","é um hábito"],ans:"está marcada"}],chunks:[{en:"I am flying tomorrow",pt:"vou voar amanhã"},{en:"we are meeting at 10",pt:"vamos nos encontrar às 10"},{en:"everything is confirmed",pt:"tudo está confirmado"}],listeningScript:"Are you coming to the conference? Yes, I am arriving on Friday. What time are you landing? At noon. Are you presenting? Yes, I am presenting the project at 3 PM. See you there!",speakingPrompt:"Conte seus compromissos: 'Tomorrow I am studying at 8. On Friday I am meeting my friend. I am flying in December.'",lightReading:"Calendars and booking systems use fixed times: the flight departs at 7, the meeting starts at 10 — schedules are present-continuous language.",journalPrompt:"Today is Day 74. I learned present continuous for fixed plans.",tip:"DICA DE APRENDIZADO: escolha a frase da semana: 'What are you doing this weekend?' Responda: 'I am [verbo+ing] on Saturday.' Treine com 3 compromissos reais."},75:{dayName:"Dia 75 — Sexta-feira",title:"Expressões de Tempo Futuro",focus:"Ancorar o futuro com tomorrow, next, in + período.",vocab:[{en:"Tomorrow",pt:"Amanhã"},{en:"Next week",pt:"Próxima semana"},{en:"Next month",pt:"Próximo mês"},{en:"In two days",pt:"Em dois dias"},{en:"In 2030",pt:"Em 2030"},{en:"By Friday",pt:"Até sexta-feira"},{en:"Before noon",pt:"Antes do meio-dia"},{en:"Later",pt:"Mais tarde"},{en:"Tonight",pt:"Hoje à noite"},{en:"Someday",pt:"Algum dia"}],grammar:{title:"Time Expressions (Futuro)",rule:"TOMORROW (amanhã), NEXT + período (next week/month/year), IN + período/ano (in two days, in 2030), BY + prazo (by Friday), TONIGHT (hoje à noite).",table:[{form:"Tomorrow / Tonight",example:"I will study tomorrow night.",pt:"Vou estudar amanhã à noite."},{form:"Next",example:"We are launching next month.",pt:"Vamos lançar no próximo mês."},{form:"In / By",example:"I will finish in two days, by Friday.",pt:"Vou terminar em dois dias, até sexta."}]},reading:{title:"Deadlines",text:"I have a deadline: the report must be ready by Friday. Tonight I will write the first part. Tomorrow I am going to finish the graphics. Next week I will present everything to the team. In two months, the whole project will be live. Someday I will manage bigger projects. Step by step!",translation:"Tenho um prazo: o relatório deve estar pronto até sexta. Hoje à noite escreverei a primeira parte. Amanhã vou terminar os gráficos. Na próxima semana apresentarei tudo à equipe. Em dois meses, o projeto inteiro estará no ar. Algum dia vou gerenciar projetos maiores. Passo a passo!"},quiz:[{q:"'By Friday' significa:",options:["até sexta-feira","na sexta de 2030","depois de sexta"],ans:"até sexta-feira"},{q:"Complete: 'I will finish ___ two days.'",options:["in","at","on"],ans:"in"},{q:"Complete: 'The report must be ready ___ Friday.'",options:["by","in","for"],ans:"by"}],chunks:[{en:"by Friday",pt:"até sexta-feira"},{en:"in two months",pt:"em dois meses"},{en:"tonight I will write",pt:"hoje à noite vou escrever"}],listeningScript:"When will the project be ready? By Friday. What are you doing tonight? I'll write the report. Next week I am presenting. In two months, everything will be live. Deadlines keep us focused!",speakingPrompt:"Ancore seu futuro: 'Tomorrow I will study. Next week I am testing. I will finish by Friday. In 2030, I will be a senior dev.'",lightReading:"Roadmaps need anchors: ship by Q3, release next sprint, deploy in two days — every plan needs a time expression.",journalPrompt:"Today is Day 75. I learned future time expressions.",tip:"DICA DE ESCRITA: BY + prazo (by Friday) = limite; IN + período (in 2 days) = tempo de execução. Usar os dois na mesma frase mostra domínio: 'I will finish in two days, by Friday.'"},76:{dayName:"Dia 76 — Sábado",title:"Futuro Completo + TESTE DE SÁBADO 11",focus:"Revisar going to, will e contínuo para futuro, e testar a semana.",vocab:[{en:"Deadline",pt:"Prazo"},{en:"Milestone",pt:"Marco"},{en:"Goal",pt:"Meta"},{en:"Target",pt:"Alvo"},{en:"Outcome",pt:"Resultado"},{en:"Aim",pt:"Objetivo"},{en:"Ambition",pt:"Ambição"},{en:"Vision",pt:"Visão"},{en:"Plan",pt:"Plano"},{en:"Projection",pt:"Projeção"}],grammar:{title:"Resumo da Semana 11",rule:"GOING TO = plano decidido. WILL = decisão na hora, promessa, previsão. PRESENT CONTINUOUS = compromisso com hora marcada. Cada um com seu tempo.",table:[{form:"Plano",example:"I am going to study React next month.",pt:"Vou estudar React no próximo mês."},{form:"Decisão/Promessa",example:"Okay, I'll help you right now!",pt:"Ok, vou te ajudar agora!"},{form:"Marcado",example:"We are meeting the client at 3 PM.",pt:"Vamos encontrar o cliente às 15h."}]},reading:{title:"My Six-Month Plan",text:"My goal is clear. In the next six months, I am going to finish this English course and build three projects. By March, I will have a portfolio. Next week I am starting a new course about databases. Maybe I will apply for a job abroad in 2027. First, I will focus on the plan. My vision is becoming real.",translation:"Minha meta está clara. Nos próximos seis meses, vou terminar este curso de inglês e construir três projetos. Até março, terei um portfólio. Na próxima semana vou começar um curso novo sobre bancos de dados. Talvez eu me candidate a um emprego no exterior em 2027. Primeiro, vou focar no plano. Minha visão está se tornando real."},quiz:[{q:"Plano decidido:",options:["I am going to build a portfolio","I built a portfolio","I build a portfolio"],ans:"I am going to build a portfolio"},{q:"Decisão na hora:",options:["Okay, I'll do it!","I am going to do it next year","I did it"],ans:"Okay, I'll do it!"},{q:"'Maybe I will apply' =",options:["talvez eu me candidate","vou me candidatar hoje","não vou me candidatar"],ans:"talvez eu me candidate"}],chunks:[{en:"I am going to finish the course",pt:"vou terminar o curso"},{en:"by March I will have a portfolio",pt:"até março terei um portfólio"},{en:"my vision is becoming real",pt:"minha visão está se tornando real"}],listeningScript:"What is your plan for the next six months? I am going to finish my English course and build projects. By March, I will have a portfolio. Next week I am starting a database course. Maybe I will apply abroad. Vision is everything!",speakingPrompt:"Apresente seu plano de 6 meses: 'My goal is... In the next months I am going to... By [mês] I will have... Maybe I will...'",lightReading:"OKRs are future-tense structures: we are going to achieve X, we will improve Y by Q4 — goals need a grammar, and that grammar is the future.",journalPrompt:"Today is Day 76. I completed my eleventh Saturday Test!",tip:"DICA DE APRENDIZADO: monte seu plano de 6 meses em 5 frases usando as 3 formas de futuro. Ter um plano em inglês é estudar o futuro e se comprometer ao mesmo tempo."},77:{dayName:"Dia 77 — Domingo",title:"Revisão da Semana 11 & Imersão Leve",focus:"Consolidar o futuro com leitura leve sobre carreira.",vocab:[{en:"Career",pt:"Carreira"},{en:"Job",pt:"Emprego"},{en:"Salary",pt:"Salário"},{en:"Promotion",pt:"Promoção"},{en:"Skill",pt:"Habilidade"},{en:"Talent",pt:"Talento"},{en:"Opportunity",pt:"Oportunidade"},{en:"Challenge",pt:"Desafio"},{en:"Experience",pt:"Experiência"},{en:"Success",pt:"Sucesso"}],grammar:{title:"Checkpoint 77 — Você fala do futuro",rule:"Seu repertório agora cobre presente, passado e futuro — a espinha dorsal de qualquer conversa em inglês.",table:[{form:"Presente",example:"I work as a developer.",pt:"Trabalho como desenvolvedor."},{form:"Passado",example:"I studied last night.",pt:"Estudei ontem à noite."},{form:"Futuro",example:"I am going to grow my career.",pt:"Vou crescer na minha carreira."}]},reading:{title:"My Career Vision",text:"I have a clear vision for my career. Now I am a junior developer, and I will become a senior. I am going to study every day and practice on real projects. Next year, I will probably take a certification. Maybe I will work for an international company. I will not stop learning, because technology never stops.",translation:"Tenho uma visão clara para minha carreira. Agora sou desenvolvedor júnior, e me tornarei sênior. Vou estudar todos os dias e praticar em projetos reais. No próximo ano, provavelmente farei uma certificação. Talvez eu trabalhe para uma empresa internacional. Não vou parar de aprender, porque a tecnologia nunca para."},quiz:[{q:"Complete: 'I ___ become a senior.'",options:["will","went","did"],ans:"will"},{q:"'I am going to study every day' =",options:["vou estudar todos os dias","estudei todos os dias","estudava todos os dias"],ans:"vou estudar todos os dias"},{q:"Complete: 'Next year I will ___ take a certification.'",options:["probably","yesterday","ago"],ans:"probably"}],chunks:[{en:"I will become a senior",pt:"me tornarei sênior"},{en:"maybe I will work abroad",pt:"talvez eu trabalhe no exterior"},{en:"technology never stops",pt:"a tecnologia nunca para"}],listeningScript:"My career plan is simple: study every day, practice on real projects, and grow step by step. Next year I will probably get a certification. Maybe I will work abroad. The future is built daily!",speakingPrompt:"Fale sua visão: 'Now I am a student. I will become a professional. I am going to study daily. Maybe I will work abroad.'",lightReading:"Career growth follows versioning: v1.0 junior, v2.0 mid, v3.0 senior — each release needs study, practice, and time to ship.",journalPrompt:"Today is Day 77. Week 11 is complete. I speak about the future!",tip:"DICA DE APRENDIZADO: domingo é ótimo para ouvir palestras curtas (10 min) em inglês sobre carreiras. Você já entende a estrutura — agora é só capturar vocabulário novo."},78:{dayName:"Dia 78 — Segunda-feira",title:"Comparativos Curtos (-er than)",focus:"Comparar com adjetivos curtos: faster, cheaper, bigger.",vocab:[{en:"Faster",pt:"Mais rápido"},{en:"Slower",pt:"Mais lento"},{en:"Cheaper",pt:"Mais barato"},{en:"Expensive",pt:"Caro"},{en:"Bigger",pt:"Maior"},{en:"Smaller",pt:"Menor"},{en:"Better",pt:"Melhor"},{en:"Worse",pt:"Pior"},{en:"Newer",pt:"Mais novo"},{en:"Older",pt:"Mais velho / Antigo"}],grammar:{title:"Comparativo Curtos",rule:"Adjetivos de 1 sílaba (fast, cheap, big) + -ER + THAN: fast -> faster than. Regras: e -> +r (large -> larger); CVC -> dobra (big -> bigger); consoante+y -> -ier (easy -> easier).",table:[{form:"+er than",example:"The new laptop is faster than the old one.",pt:"O notebook novo é mais rápido que o antigo."},{form:"Dobra consoante",example:"This screen is bigger than that one.",pt:"Esta tela é maior que aquela."},{form:"-y -> -ier",example:"React is easier than I thought.",pt:"React é mais fácil do que eu pensava."}]},reading:{title:"New vs Old",text:"I compared two laptops today. The new model is faster than my old one. It is also lighter and cheaper than the store price I saw online. The screen is bigger and clearer. However, the old laptop is more reliable for some tasks. In the end, I chose the new model: better performance, better price.",translation:"Comparei dois notebooks hoje. O modelo novo é mais rápido que o meu antigo. Ele também é mais leve e mais barato que o preço que vi online. A tela é maior e mais clara. No entanto, o notebook antigo é mais confiável para algumas tarefas. No fim, escolhi o modelo novo: melhor desempenho, melhor preço."},quiz:[{q:"Comparativo de 'fast':",options:["faster","more fast","fastest"],ans:"faster"},{q:"Complete: 'This screen is ___ than that one.'",options:["bigger","more big","biger"],ans:"bigger"},{q:"Comparativo de 'easy':",options:["easier","more easy","easyer"],ans:"easier"}],chunks:[{en:"faster than the old one",pt:"mais rápido que o antigo"},{en:"cheaper than online",pt:"mais barato que online"},{en:"better price",pt:"melhor preço"}],listeningScript:"Which laptop is better? The new one is faster and lighter. Is it cheaper? Yes, it is cheaper than the old one was. Is the screen bigger? Much bigger! I'll take the new one.",speakingPrompt:"Compare: 'My phone is newer than yours. My computer is faster. This course is easier than I thought.'",lightReading:"Benchmarks are comparative language: this framework is faster than that one, this API is cheaper per request — performance lives in -er.",journalPrompt:"Today is Day 78. I learned short comparatives.",tip:"DICA DE ESCRITA: sempre complete a comparação com THAN: 'faster THAN', 'cheaper THAN'. Sem o than, a frase fica incompleta — é o erro clássico do brasileiro."},79:{dayName:"Dia 79 — Terça-feira",title:"Comparativos Longos (More... Than)",focus:"Comparar com adjetivos longos: more efficient, more reliable.",vocab:[{en:"More efficient",pt:"Mais eficiente"},{en:"More reliable",pt:"Mais confiável"},{en:"More expensive",pt:"Mais caro"},{en:"More important",pt:"Mais importante"},{en:"More comfortable",pt:"Mais confortável"},{en:"More secure",pt:"Mais seguro"},{en:"Than",pt:"Do que"},{en:"Comparison",pt:"Comparação"},{en:"Quality",pt:"Qualidade"},{en:"Performance",pt:"Desempenho"}],grammar:{title:"Comparativo Longos",rule:"Adjetivos de 2+ sílabas: MORE + adjetivo + THAN: efficient -> more efficient than. Exceções comuns: good -> better, bad -> worse, far -> farther/further.",table:[{form:"more + adjetivo + than",example:"This framework is more efficient than that one.",pt:"Este framework é mais eficiente que aquele."},{form:"Good -> better",example:"Python is better for beginners.",pt:"Python é melhor para iniciantes."},{form:"Bad -> worse",example:"The old code is worse than the new code.",pt:"O código antigo é pior que o novo."}]},reading:{title:"Choosing a Framework",text:"Our team compared two frameworks. Framework A is more efficient than Framework B for large data. Framework B is more reliable and more secure. However, A is more popular and has more documentation. Which one is better for our project? We chose A: it is more important to be fast.",translation:"Nossa equipe comparou dois frameworks. O Framework A é mais eficiente que o B para dados grandes. O B é mais confiável e mais seguro. No entanto, o A é mais popular e tem mais documentação. Qual é melhor para nosso projeto? Escolhemos o A: é mais importante ser rápido."},quiz:[{q:"Comparativo de 'efficient':",options:["more efficient","efficienter","most efficient"],ans:"more efficient"},{q:"Comparativo de 'good':",options:["better","gooder","more good"],ans:"better"},{q:"Comparativo de 'bad':",options:["worse","badder","more bad"],ans:"worse"}],chunks:[{en:"more efficient than",pt:"mais eficiente que"},{en:"more secure and reliable",pt:"mais seguro e confiável"},{en:"better for beginners",pt:"melhor para iniciantes"}],listeningScript:"Which framework should we use? Framework A is more efficient. But B is more reliable. What about security? B is more secure. Hmm, A has more documentation. Let's choose A.",speakingPrompt:"Compare duas tecnologias: 'React is more popular than Vue. Python is easier. C++ is more powerful. English is more important than ever.'",lightReading:"Tech debates are comparative: more scalable, more maintainable, more future-proof — the entire field argues in comparatives.",journalPrompt:"Today is Day 79. I learned long comparatives.",tip:"DICA DE MEMÓRIA: 1 sílaba = -er (faster). 2+ sílabas = more (more efficient). Curto e longo: essa divisão resolve 90% dos comparativos. Os exceções (good/better, bad/worse) são poucos."},80:{dayName:"Dia 80 — Quarta-feira",title:"Superlativos Curtos (The ... -est)",focus:"Dizer o mais/algo de todos: the fastest, the biggest.",vocab:[{en:"The fastest",pt:"O mais rápido"},{en:"The biggest",pt:"O maior"},{en:"The smallest",pt:"O menor"},{en:"The cheapest",pt:"O mais barato"},{en:"The best",pt:"O melhor"},{en:"The worst",pt:"O pior"},{en:"The newest",pt:"O mais novo"},{en:"The oldest",pt:"O mais antigo"},{en:"The easiest",pt:"O mais fácil"},{en:"The hardest",pt:"O mais difícil"}],grammar:{title:"Superlativo Curtos",rule:"THE + adjetivo + -EST: fast -> the fastest. Regras iguais ao comparativo: the biggest, the easiest, the largest. THE é obrigatório no superlativo.",table:[{form:"the + -est",example:"This is the fastest computer in the office.",pt:"Este é o computador mais rápido do escritório."},{form:"Dobra / -y",example:"It is the biggest store in the city. It is the easiest test.",pt:"É a maior loja da cidade. É o teste mais fácil."},{form:"Comparativo vs superlativo",example:"A is faster than B. A is the fastest of all.",pt:"A é mais rápido que B. A é o mais rápido de todos."}]},reading:{title:"The Best Laptop",text:"I finally bought the best laptop for my budget. It has the biggest screen and the fastest processor in its category. The keyboard is the quietest I have ever used. It was not the cheapest option, but it is the most complete one. Now I am the happiest developer in the team!",translation:"Finalmente comprei o melhor notebook para meu orçamento. Ele tem a maior tela e o processador mais rápido da categoria. O teclado é o mais silencioso que já usei. Não foi a opção mais barata, mas é a mais completa. Agora sou o desenvolvedor mais feliz da equipe!"},quiz:[{q:"Superlativo de 'fast':",options:["the fastest","the more fast","fastest"],ans:"the fastest"},{q:"Complete: 'It is ___ biggest store in the city.'",options:["the","a","an"],ans:"the"},{q:"Superlativo de 'easy':",options:["the easiest","the most easy","the easyest"],ans:"the easiest"}],chunks:[{en:"the fastest processor",pt:"o processador mais rápido"},{en:"the best laptop for my budget",pt:"o melhor notebook para meu orçamento"},{en:"the happiest developer",pt:"o desenvolvedor mais feliz"}],listeningScript:"What is the best laptop for programming? This one has the fastest processor. Is it the biggest screen? No, but it is the lightest. And it is the most popular among developers. I'll take it!",speakingPrompt:"Superlativos da sua vida: 'This is the best course. English is the most important skill. Sunday is the best day.'",lightReading:"Product reviews live in superlatives: the fastest, the most secure, the best value — marketing speaks exclusively in -est.",journalPrompt:"Today is Day 80. I learned short superlatives.",tip:"DICA DE ESCRITA: superlativo SEMPRE com THE: 'the fastest', 'the best'. Sem the, é comparativo. Seu olho vai pegar esse erro em 2 segundos após 1 semana de leitura atenta."},81:{dayName:"Dia 81 — Quinta-feira",title:"Superlativos Longos & Irregulares",focus:"Usar the most + longos e os irregulares the best/the worst.",vocab:[{en:"The most reliable",pt:"O mais confiável"},{en:"The most efficient",pt:"O mais eficiente"},{en:"The most popular",pt:"O mais popular"},{en:"The most secure",pt:"O mais seguro"},{en:"The most powerful",pt:"O mais poderoso"},{en:"The most interesting",pt:"O mais interessante"},{en:"The most important",pt:"O mais importante"},{en:"The most difficult",pt:"O mais difícil"},{en:"The most amazing",pt:"O mais incrível"},{en:"The most useful",pt:"O mais útil"}],grammar:{title:"Superlativos Longos",rule:"2+ sílabas: THE MOST + adjetivo: the most reliable. Irregulares: good -> the best, bad -> the worst, far -> the farthest.",table:[{form:"the most + longo",example:"Linux is the most stable OS in our team.",pt:"Linux é o SO mais estável da nossa equipe."},{form:"Good -> the best",example:"This is the best solution for the problem.",pt:"Esta é a melhor solução para o problema."},{form:"Bad -> the worst",example:"That was the worst error I have ever made.",pt:"Esse foi o pior erro que já cometi."}]},reading:{title:"The Most Important Skill",text:"What is the most important skill in technology? Many people say communication. The most popular answer on forums is still coding, but the most useful skill is learning how to learn. The most reliable way to grow is daily practice. And the best investment of your time? English. It opens the most amazing opportunities.",translation:"Qual é a habilidade mais importante em tecnologia? Muitos dizem comunicação. A resposta mais popular nos fóruns ainda é programação, mas a habilidade mais útil é aprender a aprender. O caminho mais confiável para crescer é a prática diária. E o melhor investimento do seu tempo? Inglês. Ele abre as oportunidades mais incríveis."},quiz:[{q:"Superlativo de 'reliable':",options:["the most reliable","the reliablest","the more reliable"],ans:"the most reliable"},{q:"Superlativo de 'good':",options:["the best","the goodest","the most good"],ans:"the best"},{q:"Superlativo de 'bad':",options:["the worst","the baddest","the most bad"],ans:"the worst"}],chunks:[{en:"the most reliable way",pt:"o caminho mais confiável"},{en:"the best investment",pt:"o melhor investimento"},{en:"the most amazing opportunities",pt:"as oportunidades mais incríveis"}],listeningScript:"What is the most important thing for developers? Communication is the most valuable skill. And the best way to practice? Speak every day. It is the most useful habit you can build.",speakingPrompt:"Opine: 'English is the most important skill. React is the most popular framework. Practice is the best teacher.'",lightReading:"StackOverflow surveys are superlative databases: the most loved language, the most dreaded framework, the most wanted salary — data speaks in -est.",journalPrompt:"Today is Day 81. I learned long superlatives.",tip:"DICA DE LEITURA: em textos comparativos, mapeie: -er/-est = 1 sílaba; more/most = 2+; best/worst = exceção. Essa 'tradução mental' acelera sua leitura de reviews e comparações."},82:{dayName:"Dia 82 — Sexta-feira",title:"As... As & Igualdade",focus:"Comparar igualdade: as fast as, not as expensive as.",vocab:[{en:"As fast as",pt:"Tão rápido quanto"},{en:"Not as fast as",pt:"Não tão rápido quanto"},{en:"As good as",pt:"Tão bom quanto"},{en:"As important as",pt:"Tão importante quanto"},{en:"Same as",pt:"O mesmo que"},{en:"Different from",pt:"Diferente de"},{en:"Similar to",pt:"Parecido com"},{en:"Equal",pt:"Igual"},{en:"Comparable",pt:"Comparável"},{en:"Standard",pt:"Padrão"}],grammar:{title:"As... As (Igualdade)",rule:"AS + adjetivo + AS = igualdade: This laptop is as fast as that one. Negativa: NOT AS + adjetivo + AS = menos que: It is not as expensive as I thought.",table:[{form:"Igualdade",example:"Node is as popular as Python here.",pt:"Node é tão popular quanto Python aqui."},{form:"Negativa",example:"The new version is not as stable as the old one.",pt:"A nova versão não é tão estável quanto a antiga."},{form:"Same / different",example:"My laptop is the same as yours. It is different from mine.",pt:"Meu notebook é igual ao seu. É diferente do meu."}]},reading:{title:"Two Good Languages",text:"I love JavaScript, but my friend loves Python. Is JavaScript as easy as Python? Not as easy, but it is as powerful. Both are as popular as each other in web development. The choice is as important as the practice. Learn one, and the other becomes as familiar as a friend.",translation:"Eu amo JavaScript, mas meu amigo ama Python. JavaScript é tão fácil quanto Python? Não tão fácil, mas é tão poderoso. Ambos são tão populares quanto o outro no desenvolvimento web. A escolha é tão importante quanto a prática. Aprenda um, e o outro se torna tão familiar quanto um amigo."},quiz:[{q:"Igualdade: 'Node is ___ popular ___ Python.'",options:["as...as","more...than","the most"],ans:"as...as"},{q:"Negativa: 'It is not ___ expensive as I thought.'",options:["as","more","the"],ans:"as"},{q:"'The same as' significa:",options:["o mesmo que","diferente de","parecido com"],ans:"o mesmo que"}],chunks:[{en:"as popular as Python",pt:"tão popular quanto Python"},{en:"not as stable as the old one",pt:"não tão estável quanto a antiga"},{en:"the same as yours",pt:"o mesmo que o seu"}],listeningScript:"Is the new phone as good as the old one? Almost. The camera is as good, but the battery is not as strong. Is it as expensive? No, it is cheaper. I'll buy it!",speakingPrompt:"Compare igualdade: 'My course is as good as yours. It is not as hard as I thought. English is as important as coding.'",lightReading:"Feature parity is equality language: this API is as fast as that one, this library is not as maintained — comparisons decide migrations.",journalPrompt:"Today is Day 82. I learned as...as comparisons.",tip:"DICA DE ESCRITA: para igualdade: 'as X as Y'. Para diferença: 'X-er than Y' ou 'more X than Y'. Um par para cada — nunca misture 'as faster as' (erro típico)."},83:{dayName:"Dia 83 — Sábado",title:"Comparativos na Prática + TESTE DE SÁBADO 12",focus:"Aplicar comparativos e superlativos em escolhas reais e testar a semana.",vocab:[{en:"Choice",pt:"Escolha"},{en:"Option",pt:"Opção"},{en:"Advantage",pt:"Vantagem"},{en:"Disadvantage",pt:"Desvantagem"},{en:"Pros and cons",pt:"Prós e contras"},{en:"Preference",pt:"Preferência"},{en:"Budget",pt:"Orçamento"},{en:"Value",pt:"Valor"},{en:"Criterion",pt:"Critério"},{en:"Trade-off",pt:"Compensação / Troca"}],grammar:{title:"Resumo da Semana 12",rule:"-er than (curto), more...than (longo), the -est (superlativo curto), the most (superlativo longo), as...as (igualdade), good/better/best, bad/worse/worst.",table:[{form:"Comparativo",example:"This option is cheaper than that one.",pt:"Esta opção é mais barata que aquela."},{form:"Superlativo",example:"It is the most reliable system we have.",pt:"É o sistema mais confiável que temos."},{form:"Igualdade",example:"Both are as good as each other.",pt:"Ambos são tão bons quanto um ao outro."}]},reading:{title:"Two Options for the Project",text:"We had two options for the project: build everything in-house or use a ready platform. Building in-house is more flexible, but it is slower and more expensive. The platform is cheaper and faster to launch, but it is less customizable. The most important criterion was speed. We chose the platform. It was the best trade-off for our budget.",translation:"Tínhamos duas opções para o projeto: construir tudo internamente ou usar uma plataforma pronta. Construir internamente é mais flexível, mas é mais lento e mais caro. A plataforma é mais barata e mais rápida de lançar, mas é menos personalizável. O critério mais importante era velocidade. Escolhemos a plataforma. Foi o melhor trade-off para nosso orçamento."},quiz:[{q:"Comparativo: 'Building in-house is ___ flexible.'",options:["more","most","as"],ans:"more"},{q:"Superlativo: 'The ___ important criterion was speed.'",options:["most","more","as"],ans:"most"},{q:"'The best trade-off' =",options:["a melhor compensação","a pior escolha","a mais cara"],ans:"a melhor compensação"}],chunks:[{en:"more flexible, but slower",pt:"mais flexível, mas mais lento"},{en:"the most important criterion",pt:"o critério mais importante"},{en:"the best trade-off",pt:"a melhor compensação"}],listeningScript:"Should we build it or buy it? Building is more flexible but more expensive. The platform is faster and cheaper. What is the most important thing? Speed. Then we buy the platform. Perfect decision!",speakingPrompt:"Compare duas opções da sua vida: 'Option A is cheaper than B. B is more complete. A is the fastest. I prefer A because...'",lightReading:"Buy-vs-build decisions are comparative matrices: more cost, less control, highest risk — engineering choices are grammar comparisons.",journalPrompt:"Today is Day 83. I completed my twelfth Saturday Test!",tip:"DICA DE APRENDIZADO: crie seu 'quadro de prós e contras' em inglês: 3 vantagens (X is better/faster/cheaper) e 3 desvantagens. Decidir em inglês = praticar comparativos de verdade."},84:{dayName:"Dia 84 — Domingo",title:"Revisão da Semana 12 & Checkpoint 84",focus:"Consolidar comparativos e revisar 12 semanas de base.",vocab:[{en:"Better",pt:"Melhor"},{en:"Best",pt:"O melhor"},{en:"Worse",pt:"Pior"},{en:"Worst",pt:"O pior"},{en:"More",pt:"Mais"},{en:"Most",pt:"O mais"},{en:"Less",pt:"Menos"},{en:"Least",pt:"O menos"},{en:"Great",pt:"Ótimo"},{en:"Excellent",pt:"Excelente"}],grammar:{title:"Checkpoint 84 — A2 completo nos tempos",rule:"12 semanas: presente, contínuo, passado, futuro e comparações. Você está pronto para a consolidação A2 e o Present Perfect.",table:[{form:"Passado vs futuro",example:"I was slower last month. Now I am faster.",pt:"Eu era mais lento no mês passado. Agora sou mais rápido."},{form:"Comparação",example:"This week was better than last week. It was the best so far.",pt:"Esta semana foi melhor que a passada. Foi a melhor até agora."},{form:"Meta",example:"My English gets better every day.",pt:"Meu inglês melhora a cada dia."}]},reading:{title:"Twelve Weeks of Growth",text:"Twelve weeks ago, English was the hardest subject for me. Today it is the most interesting one. My listening is better than before, and my reading is the strongest skill. Each week was better than the last one. The best decision I made was to study every day. The future looks brighter than ever.",translation:"Doze semanas atrás, o inglês era a matéria mais difícil para mim. Hoje é a mais interessante. Meu listening está melhor que antes, e minha leitura é a habilidade mais forte. Cada semana foi melhor que a anterior. A melhor decisão que tomei foi estudar todos os dias. O futuro parece mais brilhante do que nunca."},quiz:[{q:"Complete: 'My reading is the ___ skill.'",options:["strongest","stronger","more strong"],ans:"strongest"},{q:"Complete: 'Each week was ___ than the last.'",options:["better","best","more good"],ans:"better"},{q:"'The future looks brighter than ever' =",options:["o futuro parece mais brilhante do que nunca","o futuro é incerto","o futuro é pior"],ans:"o futuro parece mais brilhante do que nunca"}],chunks:[{en:"the hardest subject",pt:"a matéria mais difícil"},{en:"better than before",pt:"melhor que antes"},{en:"brighter than ever",pt:"mais brilhante do que nunca"}],listeningScript:"Twelve weeks of study! English was the hardest subject. Now it is the most interesting. My reading is the strongest skill. Every week was better than the last. The future is brighter than ever!",speakingPrompt:"Faça seu balanço: 'Twelve weeks ago I couldn't... Now I can... My best skill is... The best decision was...'",lightReading:"Continuous improvement is a comparative game: each sprint is better than the last, each release is the best so far — growth in -er and -est.",journalPrompt:"Today is Day 84. Week 12 complete. Twelve weeks stronger!",tip:"DICA DE APRENDIZADO: escreva seu balanço mensal em inglês com 5 frases comparativas. Releia no mês seguinte: a prova do progresso está nas suas próprias frases."},85:{dayName:"Dia 85 — Segunda-feira",title:"Consolidação A2 — Revisão dos Tempos do Presente",focus:"Revisar To Be, Simple e Continuous com produção ativa.",vocab:[{en:"Consolidate",pt:"Consolidar"},{en:"Review",pt:"Revisar"},{en:"Summarize",pt:"Resumir"},{en:"Explain",pt:"Explicar"},{en:"Describe",pt:"Descrever"},{en:"Compare",pt:"Comparar"},{en:"Contrast",pt:"Contrastar"},{en:"Practice",pt:"Praticar"},{en:"Master",pt:"Dominar"},{en:"Apply",pt:"Aplicar"}],grammar:{title:"Revisão dos Presentes",rule:"TO BE: I am a developer. SIMPLE: I work every day (hábito). CONTINUOUS: I am working now (agora). Perguntas: Are you ready? Do you work? Is she working?",table:[{form:"To Be",example:"I am ready for the test.",pt:"Estou pronto para o teste."},{form:"Simple",example:"I practice every morning.",pt:"Pratico toda manhã."},{form:"Continuous",example:"I am reviewing the tenses now.",pt:"Estou revisando os tempos agora."}]},reading:{title:"My Present Reality",text:"Right now, I am reviewing everything I learned. I usually study in the morning, but today I am studying at night. I am a dedicated student, and I don't miss my goals. Do I feel tired? Sometimes, but I don't stop. Every day I practice a little, and my English is growing.",translation:"Neste momento, estou revisando tudo que aprendi. Geralmente estudo de manhã, mas hoje estou estudando à noite. Sou um estudante dedicado e não perco minhas metas. Sinto cansaço? Às vezes, mas não paro. Todos os dias pratico um pouco, e meu inglês está crescendo."},quiz:[{q:"Hábito:",options:["I usually study in the morning","I am studying now","I studied yesterday"],ans:"I usually study in the morning"},{q:"Agora:",options:["I am reviewing everything","I review everything","I reviewed everything"],ans:"I am reviewing everything"},{q:"'I don't stop' =",options:["eu não paro","eu parei","eu vou parar"],ans:"eu não paro"}],chunks:[{en:"I am a dedicated student",pt:"sou um estudante dedicado"},{en:"I don't miss my goals",pt:"não perco minhas metas"},{en:"my English is growing",pt:"meu inglês está crescendo"}],listeningScript:"What are you doing right now? I am reviewing the present tenses. Do you usually study at night? No, I usually study in the morning. But today I am studying at night. Consistency is everything!",speakingPrompt:"Autodescrição em 2 minutos: 'I am... I usually... Right now I am... I don't... Do I...? Yes, I do...'",lightReading:"Consolidation weeks are like refactoring: you rewrite what you know in a cleaner structure — same knowledge, better organization.",journalPrompt:"Today is Day 85. I started the A2 consolidation.",tip:"DICA DE APRENDIZADO: consolidação é revisão ATIVA: feche o material e escreva 5 frases de cada tempo. Escrever de memória prova o que está realmente fixado."},86:{dayName:"Dia 86 — Terça-feira",title:"Consolidação A2 — Revisão do Passado",focus:"Revisar o Past Simple regular e irregular com narrativas.",vocab:[{en:"Narrative",pt:"Narrativa"},{en:"Sequence",pt:"Sequência"},{en:"Timeline",pt:"Linha do tempo"},{en:"Episode",pt:"Episódio"},{en:"Event",pt:"Evento"},{en:"Beginning",pt:"Começo"},{en:"Middle",pt:"Meio"},{en:"End",pt:"Fim"},{en:"Then",pt:"Então / Depois"},{en:"Finally",pt:"Finalmente"}],grammar:{title:"Revisão do Passado",rule:"Regulares: +ed (worked, studied, stopped). Irregulares: went, saw, had, made, took, wrote, built, bought, found, got, said, thought, came. Negativa: didn't + base. Pergunta: Did + base.",table:[{form:"Sequência",example:"I woke up, worked, and finished the report.",pt:"Acordei, trabalhei e terminei o relatório."},{form:"Irregulares",example:"I went home and saw my friends.",pt:"Fui para casa e vi meus amigos."},{form:"Negativa",example:"I didn't buy anything. She didn't say a word.",pt:"Não comprei nada. Ela não disse uma palavra."}]},reading:{title:"My Last Weekend",text:"Last weekend, I went to the beach with my friends. We woke up early, took our bags, and drove for two hours. We saw amazing views. We didn't take photos because the phone was dead. I bought some food, and we had a great lunch. Then we played games and finally came home at night. It was a perfect weekend.",translation:"No último fim de semana, fui à praia com meus amigos. Acordamos cedo, pegamos nossas mochilas e dirigimos por duas horas. Vimos vistas incríveis. Não tiramos fotos porque o celular estava sem bateria. Comprei comida, e tivemos um ótimo almoço. Depois jogamos e finalmente voltamos para casa à noite. Foi um fim de semana perfeito."},quiz:[{q:"Sequência correta:",options:["woke up, worked, finished","wake up, work, finish","woke up, finish, worked"],ans:"woke up, worked, finished"},{q:"Complete: 'We ___ take photos.' (negativa)",options:["didn't","don't","not"],ans:"didn't"},{q:"'Finally' significa:",options:["finalmente","primeiro","depois de amanhã"],ans:"finalmente"}],chunks:[{en:"we woke up early",pt:"acordamos cedo"},{en:"we didn't take photos",pt:"não tiramos fotos"},{en:"finally we came home",pt:"finalmente voltamos para casa"}],listeningScript:"Last weekend was great. We went to the beach, woke up early, and drove for two hours. We didn't take photos because the phone was dead. We had a perfect lunch. Finally, we came home at night.",speakingPrompt:"Conte seu último fim de semana: 'Last weekend I... We woke up... We went... We didn't... Finally...'",lightReading:"Narratives need sequence words: first, then, after that, finally — the connectors that turn events into stories.",journalPrompt:"Today is Day 86. I reviewed the past with a story.",tip:"DICA DE ESCRITA: use a régua da narrativa: first (primeiro) -> then (depois) -> after that (depois disso) -> finally (finalmente). Com ela, qualquer história fica organizada."},87:{dayName:"Dia 87 — Quarta-feira",title:"Consolidação A2 — Revisão do Futuro",focus:"Revisar going to, will e contínuo para planos futuros.",vocab:[{en:"Prediction",pt:"Previsão"},{en:"Promise",pt:"Promessa"},{en:"Intention",pt:"Intenção"},{en:"Schedule",pt:"Agenda"},{en:"Project",pt:"Projeto"},{en:"Aim",pt:"Objetivo"},{en:"Forecast",pt:"Previsão (dados)"},{en:"Trend",pt:"Tendência"},{en:"Growth",pt:"Crescimento"},{en:"Progress",pt:"Progresso"}],grammar:{title:"Revisão do Futuro",rule:"GOING TO: plano (I am going to study). WILL: decisão/promessa/previsão (I'll help; It will rain). CONTINUOUS: horário marcado (I am meeting at 3).",table:[{form:"Plano",example:"I am going to change my career.",pt:"Vou mudar de carreira."},{form:"Previsão",example:"AI will create new jobs.",pt:"A IA criará novos empregos."},{form:"Marcado",example:"We are launching on Friday.",pt:"Vamos lançar na sexta."}]},reading:{title:"Next Steps",text:"Tomorrow I am starting a new project. I am going to plan everything before coding. I will probably finish the first version in two weeks. The team is meeting on Monday to review the goals. I promise I will update the documentation. In the future, this project will open new opportunities.",translation:"Amanhã vou começar um novo projeto. Vou planejar tudo antes de codificar. Provavelmente terminarei a primeira versão em duas semanas. A equipe vai se reunir na segunda para revisar as metas. Prometo que atualizarei a documentação. No futuro, este projeto abrirá novas oportunidades."},quiz:[{q:"Plano decidido:",options:["I am going to plan everything","I planned everything","I plan everything"],ans:"I am going to plan everything"},{q:"Previsão:",options:["I will probably finish in two weeks","I finished in two weeks","I am finishing yesterday"],ans:"I will probably finish in two weeks"},{q:"Horário marcado:",options:["The team is meeting on Monday","The team met on Monday","The team meets Mondays habitually"],ans:"The team is meeting on Monday"}],chunks:[{en:"I will probably finish in two weeks",pt:"provavelmente terminarei em duas semanas"},{en:"I promise I will update the docs",pt:"prometo que atualizarei a documentação"},{en:"the team is meeting on Monday",pt:"a equipe vai se reunir na segunda"}],listeningScript:"What is your plan for next month? I am going to start a new project. When is the team meeting? On Monday. Will you finish soon? I will probably finish in two weeks. Good luck!",speakingPrompt:"Fale seus próximos passos: 'Tomorrow I am... I am going to... I will probably... The team is... I promise I will...'",lightReading:"Sprint planning is a future-tense meeting: we are going to commit, we will deliver, the demo is scheduled — plans, promises, and calendars in one.",journalPrompt:"Today is Day 87. I reviewed the future tenses.",tip:"DICA DE APRENDIZADO: ao revisar, escolha UMA forma por dia: hoje só going to, amanhã só will. Foco único consolida mais rápido que revisar tudo de uma vez."},88:{dayName:"Dia 88 — Quinta-feira",title:"Conjunções: And, But, Or",focus:"Ligar ideias com and (adição), but (contraste) e or (alternativa).",vocab:[{en:"And",pt:"E"},{en:"But",pt:"Mas"},{en:"Or",pt:"Ou"},{en:"Choice",pt:"Escolha"},{en:"Contrast",pt:"Contraste"},{en:"Addition",pt:"Adição"},{en:"Alternative",pt:"Alternativa"},{en:"Either",pt:"Ou... ou (um ou outro)"},{en:"Neither",pt:"Nem (nenhum dos dois)"},{en:"Both",pt:"Ambos"}],grammar:{title:"And / But / Or",rule:"AND junta ideias iguais (I like coding and reading). BUT contrasta (I like coding, but I don't like meetings). OR oferece escolha (Do you want tea or coffee?).",table:[{form:"And (adição)",example:"I studied grammar and practiced listening.",pt:"Estudei gramática e pratiquei listening."},{form:"But (contraste)",example:"The code works, but it is slow.",pt:"O código funciona, mas é lento."},{form:"Or (escolha)",example:"Do you prefer Git or GitHub?",pt:"Você prefere Git ou GitHub?"}]},reading:{title:"My Preferences",text:"I love frontend and backend, but I prefer backend. Do I like databases or networks? I like databases, but I also enjoy networks. Every morning I study grammar and read an article. Do I prefer coffee or tea? Coffee, but only in the morning. Simple choices make my day.",translation:"Amo frontend e backend, mas prefiro backend. Gosto de bancos de dados ou redes? Gosto de bancos, mas também curto redes. Toda manhã estudo gramática e leio um artigo. Prefiro café ou chá? Café, mas só de manhã. Escolhas simples fazem meu dia."},quiz:[{q:"Contraste:",options:["I like coding, but I don't like meetings","I like coding and meetings","Coding or meetings"],ans:"I like coding, but I don't like meetings"},{q:"Escolha:",options:["Tea or coffee?","Tea and coffee!","Tea but coffee"],ans:"Tea or coffee?"},{q:"Adição:",options:["I studied grammar and practiced listening","I studied grammar but practiced listening","Grammar or listening"],ans:"I studied grammar and practiced listening"}],chunks:[{en:"I love frontend and backend",pt:"amo frontend e backend"},{en:"but I prefer backend",pt:"mas prefiro backend"},{en:"tea or coffee?",pt:"chá ou café?"}],listeningScript:"Do you want to study now or later? Later, but only for one hour. I will study grammar and practice speaking. Good plan!",speakingPrompt:"Ligue ideias: 'I like X and Y, but I prefer Z. Do I prefer A or B? I choose B, but only sometimes.'",lightReading:"Logic operators are conjunctions: AND, OR, NOT — English conjunctions and boolean algebra share the same three words.",journalPrompt:"Today is Day 88. I learned and, but and or.",tip:"DICA DE ESCRITA: cada conjunção tem um papel: AND soma, BUT vira, OR oferece. Antes de escrever, pergunte: quero somar, virar ou oferecer? A resposta decide a conjunção."},89:{dayName:"Dia 89 — Sexta-feira",title:"Conjunções: Because, So, Although",focus:"Explicar causas e consequências com because, so e although.",vocab:[{en:"Because",pt:"Porque"},{en:"So",pt:"Então / Por isso"},{en:"Although",pt:"Embora / Apesar de"},{en:"Reason",pt:"Motivo"},{en:"Result",pt:"Resultado"},{en:"Cause",pt:"Causa"},{en:"Effect",pt:"Efeito"},{en:"Therefore",pt:"Portanto"},{en:"However",pt:"No entanto"},{en:"Consequence",pt:"Consequência"}],grammar:{title:"Because / So / Although",rule:"BECAUSE dá o motivo (I study because I want to grow). SO dá o resultado (I studied, so I passed). ALTHOUGH mostra contraste surpreendente (Although it was hard, I finished).",table:[{form:"Because (motivo)",example:"I practice daily because I want to be fluent.",pt:"Pratico diariamente porque quero ser fluente."},{form:"So (resultado)",example:"The server crashed, so we lost some data.",pt:"O servidor travou, então perdemos alguns dados."},{form:"Although (contraste)",example:"Although I was tired, I finished the task.",pt:"Embora estivesse cansado, terminei a tarefa."}]},reading:{title:"Why I Study Every Day",text:"I study every day because I have a clear goal. My goal is to work with international teams, so English is essential. Although it is difficult sometimes, I never give up. I wake up early because mornings are quiet. I review at night because repetition fixes memory. So my progress is constant.",translation:"Estudo todos os dias porque tenho uma meta clara. Minha meta é trabalhar com equipes internacionais, então o inglês é essencial. Embora às vezes seja difícil, nunca desisto. Acordo cedo porque as manhãs são silenciosas. Reviso à noite porque a repetição fixa a memória. Por isso meu progresso é constante."},quiz:[{q:"Motivo:",options:["I study because I want to grow","I study so I grew","I study although I want"],ans:"I study because I want to grow"},{q:"Resultado:",options:["I studied, so I passed","I studied because I passed","Although I studied, I passed"],ans:"I studied, so I passed"},{q:"Contraste:",options:["Although it was hard, I finished","It was hard because I finished","It was hard so I finished"],ans:"Although it was hard, I finished"}],chunks:[{en:"I study because I have a goal",pt:"estudo porque tenho uma meta"},{en:"English is essential, so I practice",pt:"o inglês é essencial, então pratico"},{en:"although it is hard, I never give up",pt:"embora seja difícil, nunca desisto"}],listeningScript:"Why do you wake up early? Because the morning is quiet. Why do you review at night? Because repetition fixes memory. It is hard sometimes. Although it is hard, I never give up!",speakingPrompt:"Explique suas escolhas: 'I study because... My goal is..., so... Although..., I...'",lightReading:"Postmortems use cause-effect language: the incident happened because X, so we added a check; although the impact was small, we improved the process.",journalPrompt:"Today is Day 89. I learned because, so and although.",tip:"DICA DE LEITURA: porque = reason; so = result; although = surprise. Ao ler, identifique o papel de cada conjunção — isso revela a lógica inteira do parágrafo."},90:{dayName:"Dia 90 — Sábado",title:"Consolidação Final A2 + TESTE DE SÁBADO 13",focus:"Testar a consolidação A2 completa: tempos, comparações e conjunções.",vocab:[{en:"Consolidation",pt:"Consolidação"},{en:"Milestone",pt:"Marco"},{en:"Review",pt:"Revisão"},{en:"Achievement",pt:"Conquista"},{en:"Foundation",pt:"Fundação"},{en:"Confidence",pt:"Confiança"},{en:"Skill",pt:"Habilidade"},{en:"Knowledge",pt:"Conhecimento"},{en:"Progress",pt:"Progresso"},{en:"Success",pt:"Sucesso"}],grammar:{title:"Checkpoint 90 — A2 Consolidado!",rule:"90 dias: A1 completo + A2 em consolidação. Você fala do presente, passado e futuro, compara coisas, explica causas e consequências, e lê textos simples com confiança.",table:[{form:"Tempos",example:"I studied, I am studying, and I will study.",pt:"Estudei, estou estudando e estudarei."},{form:"Comparação",example:"This month is better than last month.",pt:"Este mês é melhor que o passado."},{form:"Causa e efeito",example:"I practice daily, so my English improves.",pt:"Pratico diariamente, então meu inglês melhora."}]},reading:{title:"Ninety Days of English",text:"Today is my 90-day milestone. Although I had doubts at the beginning, I never stopped. I studied every day, so my base is solid. My reading is better than before, and my listening is improving. Because I review constantly, I remember more words. The best part? I understand short stories now. The next 90 days will be even better.",translation:"Hoje é meu marco de 90 dias. Embora tivesse dúvidas no começo, nunca parei. Estudei todos os dias, então minha base é sólida. Minha leitura está melhor que antes, e meu listening está melhorando. Porque reviso constantemente, lembro mais palavras. A melhor parte? Agora entendo histórias curtas. Os próximos 90 dias serão ainda melhores."},quiz:[{q:"Complete: 'I never stopped, ___ my base is solid.'",options:["so","because","although"],ans:"so"},{q:"Complete: '___ I review constantly, I remember more.'",options:["Because","So","But"],ans:"Because"},{q:"Complete: 'My reading is ___ than before.'",options:["better","best","gooder"],ans:"better"}],chunks:[{en:"my 90-day milestone",pt:"meu marco de 90 dias"},{en:"I never stopped",pt:"nunca parei"},{en:"my base is solid",pt:"minha base é sólida"}],listeningScript:"Congratulations! You are at your 90-day milestone. Although it was hard, you never stopped. Your base is solid, and your reading is better than before. The next 90 days will bring the Present Perfect and professional English!",speakingPrompt:"Fale seu marco: 'Today is my 90-day milestone. Although it was hard, I never stopped. Because I practice daily, my English improves. The future will be even better.'",lightReading:"Day 90 is the halfway release: version A2 is stable, tested, and ready for the professional modules — like software, progress ships in milestones.",journalPrompt:"Today is Day 90. The A2 foundation is consolidated. Halfway there!",tip:"DICA DE APRENDIZADO: comemore o marco fazendo um 'teste real': escolha uma história curta em inglês, leia sem traduzir, e resuma em 5 frases. Você verá o quanto já entende."}},a=[{id:11,title:"Semana 11 — Futuro: Going To & Will",daysRange:"Dias 71 a 77",subtitle:"Planos, Decisões, Previsões e Horários",badgeClass:"badge-blue",grammar:["Be going to (planos e intenções)","Will (decisões instantâneas, promessas e previsões)","Probably / Maybe / Definitely","Present Continuous para compromissos fixos","Expressões de tempo futuro (tomorrow, next, in, by)"],vocab:"Projetos futuros, metas de carreira em TI e planejamento (1000+ palavras)",reading:"Roteiros de aprendizagem e artigos sobre o futuro da tecnologia",listening:"Conversas sobre planos e previsões",speaking:"Falar sobre planos de estudo e carreira para os próximos 6 meses",techBridge:"Frases: 'I am going to build an API', 'AI will transform software', 'We are launching next week'",saturday:{recall:[["I am going to learn React","vou aprender React"],["we are going to launch an app","vamos lançar um app"],["I am not going to stop","não vou parar"],["I'll check the cables","vou verificar os cabos"],["I promise I will help","prometo que vou ajudar"],["it will probably work","provavelmente vai funcionar"],["maybe I will study abroad","talvez eu estude no exterior"],["I am flying tomorrow","vou voar amanhã"],["we are meeting at 10","vamos nos encontrar às 10"],["by Friday","até sexta-feira"],["in two months","em dois meses"],["my vision is becoming real","minha visão está se tornando real"]],reading:{title:"The Six-Month Roadmap",text:"My roadmap for the next six months is ready. Next week I am starting a database course. In March, I am going to finish my portfolio. I will probably build three projects before June. Maybe I will join a study group, because groups are better for motivation. Although I have a busy schedule, I am going to study English every day. By December, I will have a complete profile for international jobs. The plan is clear, so I just need discipline.",questions:["When is the database course starting?","What will the writer finish in March?","Why are study groups better?","What is the writer going to do every day?","What will the writer have by December?"]},listening:"Listen: 'My roadmap is ready. Next week I am starting a new course. In March I am going to finish my portfolio. I will probably build three projects. Although I am busy, I will study English daily. By December, I will be ready for international jobs!'",speaking:"Apresente seu plano de 6 meses: 'Next week I am... In [mês] I am going to... I will probably... Maybe I will... By [data] I will have...'"}},{id:12,title:"Semana 12 — Comparativos & Superlativos",daysRange:"Dias 78 a 84",subtitle:"-er, more, the -est, the most, as...as",badgeClass:"badge-purple",grammar:["Comparatives curtos (-er than)","Comparatives longos (more...than)","Superlatives curtos (the -est)","Superlatives longos (the most) + irregulares (best/worst)","As...as (igualdade) e not as...as"],vocab:"Comparação de linguagens, sistemas e desempenho",reading:"Artigos comparativos (Python vs JavaScript, frameworks)",listening:"Reviews e comparações de produtos e tecnologias",speaking:"Comparar dois computadores ou linguagens em inglês simples",techBridge:"Frases: 'C++ is faster than Python', 'Linux is the most stable OS'",saturday:{recall:[["faster than the old one","mais rápido que o antigo"],["cheaper than online","mais barato que online"],["more efficient than","mais eficiente que"],["more secure and reliable","mais seguro e confiável"],["better for beginners","melhor para iniciantes"],["the fastest processor","o processador mais rápido"],["the best laptop for my budget","o melhor notebook para meu orçamento"],["the most reliable way","o caminho mais confiável"],["the best investment","o melhor investimento"],["as popular as Python","tão popular quanto Python"],["not as stable as the old one","não tão estável quanto a antiga"],["the most important criterion","o critério mais importante"]],reading:{title:"Python or JavaScript?",text:"Which language is better for a beginner: Python or JavaScript? Python is easier and has simpler syntax. JavaScript is more flexible because it works everywhere. Python is better for data and artificial intelligence. JavaScript is the best choice for web pages. Both are as popular as each other, but Python is growing faster. The most important thing is your goal: choose the tool that is more useful for your path. And remember: the best language is the one you practice!",questions:["Why is Python easier?","What is JavaScript better for?","Which is growing faster?","What is the most important thing?","What is 'the best language'?"]},listening:"Listen: 'Python or JavaScript? Python is easier for beginners. JavaScript is more flexible. Python is better for AI. JavaScript is the best for web. The most important thing is your goal. Practice is the best teacher!'",speaking:"Compare duas tecnologias da sua área: 'X is faster than Y. Y is more popular. Z is the most powerful. A is as good as B...'"}},{id:13,title:"Semana 13 — Consolidação A2",daysRange:"Dias 85 a 90",subtitle:"Revisão dos Tempos & Conjunções",badgeClass:"badge-emerald",grammar:["Revisão geral dos tempos (presente, passado, futuro)","Conjunctions: and, but, or","Conjunctions: because, so, although","Produção ativa: narrativas e explicações"],vocab:"1.500+ palavras ativas. Mudança do ambiente para inglês",reading:"Histórias curtas e artigos A2 completos",listening:"Escuta ativa 60-90 min/dia em 1.0x",speaking:"Speaking solo diário de 20-30 minutos",techBridge:"Pesquisar dúvidas de programação em inglês no Google",saturday:{recall:[["I am a dedicated student","sou um estudante dedicado"],["my English is growing","meu inglês está crescendo"],["we woke up early","acordamos cedo"],["finally we came home","finalmente voltamos para casa"],["I will probably finish in two weeks","provavelmente terminarei em duas semanas"],["the team is meeting on Monday","a equipe vai se reunir na segunda"],["I like coding, but I don't like meetings","gosto de codar, mas não gosto de reuniões"],["tea or coffee?","chá ou café?"],["I study because I have a goal","estudo porque tenho uma meta"],["I studied, so I passed","estudei, então passei"],["although it is hard, I never give up","embora seja difícil, nunca desisto"],["my base is solid","minha base é sólida"]],reading:{title:"The Road to Fluency",text:"Learning English is a journey with many steps. Although the beginning was hard, I never stopped. I studied grammar and vocabulary every day, so my base became solid. My listening is better than before, but my speaking is still slow. Because I practice daily, I am improving. Last week I understood a full video without subtitles, and I was very happy. Next month I will start the professional module. My goal is clear, and I am following the roadmap.",questions:["How was the beginning of the journey?","Why did the base become solid?","What skill is still slow?","What happened last week?","What will happen next month?"]},listening:"Listen: 'Learning English is a journey. Although it was hard, I never stopped. My base is solid because I practice daily. Last week I understood a video without subtitles! Next month I start the professional module. The goal is clear!'",speaking:"Fale seu marco de 90 dias: 'Although..., I... Because..., my... My best skill is... Next month I will...'"}}];export{e as d,a as w};
